#include <Wire.h>
#include <Adafruit_PWMServoDriver.h>

Adafruit_PWMServoDriver pwm;   // the board at its default address, 0x40
int last = -1;

void report(int deg, int us) {
  Serial.print("base ");
  Serial.print(deg);
  Serial.print(" deg = ");
  Serial.print(us);
  Serial.println(" us");
}

void setup() {
  Serial.begin(9600);
  pwm.begin();
  pwm.setPWMFreq(50);
}

void loop() {
  int deg = map(analogRead(A0), 0, 1023, 0, 180);
  int us = map(deg, 0, 180, 600, 2400);
  pwm.writeMicroseconds(0, us);
  if (deg != last) {
    report(deg, us);
    last = deg;
  }
  delay(50);
}

